            {{Members}}
            }
            """;

        await new VerifyCS.Test
        {
            TestState =
            {
                Sources = { testSource },
            },
            ExpectedDiagnostics = { DiagnosticResult.CompilerError("MsgPack005").WithLocation(0) },
        }.RunDefaultAsync(this.testOutputHelper);
    }
